# Who held a permission of the old logs gets its successor (the stock dialog needed add_stockchange).
SUCCESSORS = {
    ("stockchange", "add_stockchange"): ("itemlocation", "change_stock", "Can remove and add stock in the stock dialog"),
    ("stockchange", "view_stockchange"): ("changelog", "view_changelog", "Can view change log entry"),
    ("uniqueitemevent", "view_uniqueitemevent"): ("changelog", "view_changelog", "Can view change log entry"),
    ("locationhistory", "view_locationhistory"): ("changelog", "view_changelog", "Can view change log entry"),
}


def grant_change_log(apps, schema_editor):
    """The local group sees changes and uses the stock dialog, CHANGE_LOG_ACTOR_GROUP also sees who made them."""
    alias = schema_editor.connection.alias
    Group = apps.get_model("auth", "Group")
    Permission = apps.get_model("auth", "Permission")
    ContentType = apps.get_model("contenttypes", "ContentType")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))

    def permission(model, codename, name):
        content_type, _ = ContentType.objects.using(alias).get_or_create(app_label="inventory", model=model)
        found, _ = Permission.objects.using(alias).get_or_create(
            content_type=content_type, codename=codename, defaults={"name": name})
        return found

    for (model, codename), successor in SUCCESSORS.items():
        old = Permission.objects.using(alias).filter(content_type__app_label="inventory",
                                                     content_type__model=model, codename=codename).first()
        if old is None:
            continue
        new = permission(*successor)
        for group in Group.objects.using(alias).filter(permissions=old):
            group.permissions.add(new)
        for user in User.objects.using(alias).filter(user_permissions=old):
            user.user_permissions.add(new)
    view = permission("changelog", "view_changelog", "Can view change log entry")
    stock = permission("itemlocation", "change_stock", "Can remove and add stock in the stock dialog")
    actor = permission("changelog", "view_changelog_actor", "Can see who made a change in the change log")
    local, _ = Group.objects.using(alias).get_or_create(name=settings.LOCAL_GROUP_NAME)
    local.permissions.add(view, stock)
    active, _ = Group.objects.using(alias).get_or_create(name=settings.CHANGE_LOG_ACTOR_GROUP)
    active.permissions.add(view, actor)


